// Builds ./sim.gen.js: the Operation Blacksite engine for the multiplayer game server (a Cloudflare Durable Object, see ./room.js).
// The same rules as the browser game, without the 3D world, effects, sound and models (./visualStubs.js stands in for those).
//
// Run it again whenever blacksite/engine/* changes:   npm run build:mpsim
// The generated file is committed, so deploying needs nothing extra.
import { build } from "esbuild";
import { fileURLToPath } from "node:url";
import path from "node:path";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "../..");
const STUB = path.join(here, "visualStubs.js");
const VISUAL = new Set(["./world", "./fx", "./viewmodel", "./sfx", "./soldier", "@/lib/cinematic/post", "@/lib/cinematic/music", "@/lib/gpuTier", "three/examples/jsm/postprocessing/RenderPass.js"]);

await build({
  entryPoints: [path.join(root, "blacksite/engine/engine.js")],
  outfile: path.join(here, "sim.gen.js"),
  bundle: true, format: "esm", platform: "neutral", target: "es2022", minify: true, legalComments: "none", mainFields: ["module", "main"],
  banner: { js: "// GENERATED by blacksite/server/buildSim.mjs from blacksite/engine — do not edit by hand. Rebuild with: npm run build:mpsim" },
  plugins: [{
    name: "server-stubs",
    setup(b) {
      b.onResolve({ filter: /.*/ }, (a) => {
        if (VISUAL.has(a.path)) return { path: STUB };
        if (a.path.startsWith("@/")) return { path: path.join(root, a.path.slice(2)) + (path.extname(a.path) ? "" : ".js") };
        return null;
      });
    },
  }],
  logLevel: "warning",
});
console.log("built blacksite/server/sim.gen.js");
